args.sparql:
SELECT DISTINCT ?director ?directorLabel ?spouse ?spouseLabel WHERE {
  dbr:The_Invisible_Menace dbo:director ?director .
  ?director (dbo:spouse|dbp:spouse) ?spouse .
  FILTER(isIRI(?spouse))
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }
  OPTIONAL { ?spouse rdfs:label ?spouseLabel FILTER(lang(?spouseLabel) = 'en') }
}

output.sparql:
